// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait ServiceActivityAssessment_Api {
  def id: Art.BridgeId
  def service_activity_Id : Art.PortId
  def service_readiness_Id : Art.PortId
  def service_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var service_readiness: Docking_Access_Supervisor.ServiceFacts = $

  def put_service_readiness(value : Docking_Access_Supervisor.ServiceFacts) : Unit = {
    Contract(
      Modifies(service_readiness),
      Ensures(
        service_readiness == value
      )
    )
    Spec {
      service_readiness = value
    }

    Art.putValue(service_readiness_Id, Docking_Access_Supervisor.ServiceFacts_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var service_facts: Docking_Access_Supervisor.ServiceFacts = $

  def put_service_facts(value : Docking_Access_Supervisor.ServiceFacts) : Unit = {
    Contract(
      Modifies(service_facts),
      Ensures(
        service_facts == value
      )
    )
    Spec {
      service_facts = value
    }

    Art.putValue(service_facts_Id, Docking_Access_Supervisor.ServiceFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ServiceActivityAssessment_Initialization_Api (
  val id: Art.BridgeId,
  val service_activity_Id : Art.PortId,
  val service_readiness_Id : Art.PortId,
  val service_facts_Id : Art.PortId) extends ServiceActivityAssessment_Api

@datatype class ServiceActivityAssessment_Operational_Api (
  val id: Art.BridgeId,
  val service_activity_Id : Art.PortId,
  val service_readiness_Id : Art.PortId,
  val service_facts_Id : Art.PortId) extends ServiceActivityAssessment_Api {

  // Logika spec var representing port state for incoming data port
  @spec var service_activity: Docking_Access_Supervisor.ServiceActivity.Type = $

  def get_service_activity() : Option[Docking_Access_Supervisor.ServiceActivity.Type] = {
    Contract(
      Ensures(
        Res == Some(service_activity)
      )
    )
    val value : Option[Docking_Access_Supervisor.ServiceActivity.Type] = Art.getValue(service_activity_Id) match {
      case Some(Docking_Access_Supervisor.ServiceActivity_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port service_activity.  Expecting 'Docking_Access_Supervisor.ServiceActivity_Payload' but received ${v}")
        None[Docking_Access_Supervisor.ServiceActivity.Type]()
      case _ => None[Docking_Access_Supervisor.ServiceActivity.Type]()
    }
    return value
  }
}
